import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CyZTVJbV.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.20/x-thread-en.md","filePath":"announcements/v1.20/x-thread-en.md"}'),s={name:"announcements/v1.20/x-thread-en.md"};function c(d,e,n,i,m,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<p>1/ kiwa v1.20 is out — Streaming 深化 milestone. After v1.19&#39;s Framework 深化 horizontal (SolidJS Signal + Deno Fresh Islands + HonoJS Cloudflare Workers), v1.20 lands <strong>the event-driven backbone</strong> every SaaS + data team already ships: Kafka (kafkajs-shaped producer / consumer / admin) + Redpanda (Kafka API 互換 + schema registry) + NATS (core pub/sub + JetStream + KV / Object store). One unified mock, five semantics, zero brokers.</p><p>2/ <code>@kiwa-test/streaming</code> v0.1.0 — 3 provider unified testing mock. <code>createKafkaMock({ defaultPartitionCount })</code> returns broker + producer + consumer + admin (kafkajs-shaped, deterministic djb2 key-hash partitioner, <code>partitionAssigner: &#39;range&#39; | &#39;round-robin&#39;</code>). <code>createRedpandaMock({ schemaRegistry: true })</code> layers a colocated <code>SchemaRegistry</code> on a Kafka-shaped broker. <code>createNatsMock()</code> gives core pub/sub with <code>*</code> (single-token) + <code>&gt;</code> (multi-token) subject routing + <code>nats.jetstream()</code> persistent streams + <code>js.kv</code> + <code>js.objectStore</code>. 104 behavior tests.</p><p>3/ Producer + consumer semantics — Kafka producer.send routes on hash(key) mod partitionCount, records the partition + offset for every write, <code>sendBatch</code> flattens across topics. <code>consumer.run({ eachMessage, autoCommit })</code> walks each assigned partition, <code>commitOffsets(offsets[])</code> records explicit offsets, <code>getCommittedOffset(groupId, topic, partition)</code> surfaces the durable marker. Rebalance recomputes assignments deterministically when a member joins/leaves.</p><p>4/ Exactly-once semantics — <code>createTransactionalProducer(kafka, { transactionalId })</code> gives atomic multi-record commit + abort, <code>createIdempotentProducer(kafka, { producerId })</code> gives per-partition sequence dedup (retry-safe), <code>createReadCommittedFilter(consumer)</code> filters uncommitted / aborted transactions from downstream reads. Three helpers cover the exactly-once pillars end-to-end without a broker.</p><p>5/ DLQ + schema registry — <code>createDeadLetterQueue({ maxRetries, backoffExponent })</code> layers retry policy + poison message quarantine + inspect + reprocess flow on any consumer. <code>createSchemaRegistry()</code> gives <code>registerAvro</code> / <code>registerProtobuf</code> / <code>registerJson</code> + three compatibility modes (<code>BACKWARD</code> / <code>FORWARD</code> / <code>FULL</code>) + schema evolution + fail-fast publish gating. Kafka + Redpanda + NATS all share the same mock surface.</p><p>6/ dogfood apps — <code>dogfood-kafka-event-pipeline</code> (Kafka producer + consumer group + exactly-once transactional producer + DLQ fidelity harness, 5 scenario) + <code>dogfood-redpanda-schema-registry</code> (Redpanda + 3 Avro schemas × BACKWARD / FORWARD / FULL + fail-fast + Kafka API round-trip, 5 scenario) + <code>dogfood-nats-jetstream</code> (NATS core pub/sub + wildcards + JetStream + KV + Object store, 5 scenario). All 3 hit 7-axis release gate PASS.</p><p>7/ 1 new npm package published — <code>@kiwa-test/streaming</code> v0.1.0 to npm. kiwa runtime fixture count is now 34 packages. docs: 3 tutorials (31 Kafka + 32 Redpanda + schema registry + 33 NATS JetStream) + additive migration v1.19 → v1.20 + concept doc <code>streaming-testing.md</code> (5 semantics × 6 semantic axis SSOT). VitePress + gh-pages published. Roadmap: <a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa#roadmap</a> — v1.11 → v1.12 → v1.13 → v1.14 → v1.15 → v1.16 → v1.17 → v1.18 → v1.19 → v1.20: 10 milestones in a row.</p>',7)])])}const f=o(s,[["render",c]]);export{l as __pageData,f as default};
